import{_ as a,c as t,o,aj as r}from"./chunks/framework.BlveriQe.js";const m=JSON.parse('{"title":"Interface: CreateDatabaseParams","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/CreateDatabaseParams.md","filePath":"reference/js-bao-wss-client/api/interfaces/CreateDatabaseParams.md"}'),c={name:"reference/js-bao-wss-client/api/interfaces/CreateDatabaseParams.md"};function d(s,e,i,n,l,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / CreateDatabaseParams</p><h1 id="interface-createdatabaseparams" tabindex="-1">Interface: CreateDatabaseParams <a class="header-anchor" href="#interface-createdatabaseparams" aria-label="Permalink to “Interface: CreateDatabaseParams”">​</a></h1><p>Parameters for <code>databases.create()</code>.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="celcontext" tabindex="-1"><s>celContext?</s> <a class="header-anchor" href="#celcontext" aria-label="Permalink to “celContext?”">​</a></h3><blockquote><p><code>optional</code> <strong>celContext?</strong>: <code>Record</code>&lt;<code>string</code>, <code>string</code> | <code>number</code> | <code>boolean</code> | <code>null</code>&gt;</p></blockquote><p>Optional key-value pairs to attach as the database&#39;s CEL context. Values set here can be referenced from CEL access rules as <code>database.celContext.&lt;key&gt;</code> (or the legacy <code>database.metadata.&lt;key&gt;</code>) and from filter JSON as <code>$database.celContext.&lt;key&gt;</code>.</p><h4 id="deprecated" tabindex="-1">Deprecated <a class="header-anchor" href="#deprecated" aria-label="Permalink to “Deprecated”">​</a></h4><p>Prefer resource metadata categories — a category has separate <code>readRule</code>/<code>writeRule</code> (read no longer implies update, unlike the <code>metadataAccess</code> gate) and is read from CEL as <code>md.self.&lt;category&gt;.&lt;key&gt;</code>. Stamp create-time category values via <a href="#initialmetadata">initialMetadata</a> instead. See the migration recipe in <code>databases.md</code>. The field keeps working.</p><hr><h3 id="databasetype" tabindex="-1">databaseType <a class="header-anchor" href="#databasetype" aria-label="Permalink to “databaseType”">​</a></h3><blockquote><p><strong>databaseType</strong>: <code>string</code></p></blockquote><p>The type identifier for the database schema</p><hr><h3 id="initialmetadata" tabindex="-1">initialMetadata? <a class="header-anchor" href="#initialmetadata" aria-label="Permalink to “initialMetadata?”">​</a></h3><blockquote><p><code>optional</code> <strong>initialMetadata?</strong>: <code>Record</code>&lt;<code>string</code>, <code>Record</code>&lt;<code>string</code>, <code>unknown</code>&gt;&gt;</p></blockquote><p>Optional. Create-time resource metadata to stamp on the new database, keyed by category name → the category&#39;s values. Distinct from <a href="#celcontext">celContext</a>: these are per-category <code>ResourceMetadata</code> rows, schema-validated with the category <code>writeRule</code> waived (creation authority covers the initial stamp). At most 10 categories; any invalid entry fails the whole create.</p><hr><h3 id="metadata" tabindex="-1"><s>metadata?</s> <a class="header-anchor" href="#metadata" aria-label="Permalink to “metadata?”">​</a></h3><blockquote><p><code>optional</code> <strong>metadata?</strong>: <code>Record</code>&lt;<code>string</code>, <code>string</code> | <code>number</code> | <code>boolean</code> | <code>null</code>&gt;</p></blockquote><p>Optional key-value pairs to attach as the database&#39;s CEL context.</p><h4 id="deprecated-1" tabindex="-1">Deprecated <a class="header-anchor" href="#deprecated-1" aria-label="Permalink to “Deprecated”">​</a></h4><p>Prefer resource metadata categories — a category has separate <code>readRule</code>/<code>writeRule</code> and is read from CEL as <code>md.self.&lt;category&gt;.&lt;key&gt;</code>. See the migration recipe in <code>databases.md</code>. The legacy name (&quot;metadata&quot;) is the same field as the (also-deprecated) <a href="#celcontext">celContext</a> and still works.</p><hr><h3 id="title" tabindex="-1">title <a class="header-anchor" href="#title" aria-label="Permalink to “title”">​</a></h3><blockquote><p><strong>title</strong>: <code>string</code></p></blockquote><p>Display name for the database</p>',29)])])}const b=a(c,[["render",d]]);export{m as __pageData,b as default};
